insert into public.site_content(key,data) values('general',$j${"brand":"Hartwell","tagline":"Product designer","primary":"#2b4f35","accent":"#ffab00","announce_on":false,"announce_text":"Booking projects for next quarter","announce_link":"/contact","footer_text":"© Hartwell. Crafted with care.","cta_label":"Contact Me","cta_link":"/contact"}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('seo',$j${"title":"Hartwell — Product Designer","description":"Portfolio of Maya Hartwell, a product designer crafting calm, usable interfaces.","og_image":"https://randomuser.me/api/portraits/women/44.jpg"}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('hero',$j${"badge":"Hello There!","title_pre":"I’m ","name":"Maya Hartwell,","title":"Product Designer\nBased in Canada.","text":"Product designer with 12 years of experience shaping apps and platforms for startups and established teams.","btn1":"View My Portfolio","btn1_link":"/projects","btn2":"Hire Me","btn2_link":"/contact","image":"/hero-cutout.png","chip1":"Product Designer","chip2":"UI/UX Designer","marquee":["App Design","Website Design","Dashboard","Wireframing","Design Systems"]}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('services_intro',$j${"eyebrow":"Services","title":"Services","title_accent":"I Provide","btn":"View All Services","link":"/services"}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('about',$j${"eyebrow":"About Me","title":"Who is","name":"Maya Hartwell?","text":"I turn tangled ideas into clear, friendly products. My work blends research, systems thinking and a love for small details that make software feel effortless.","image":"/about-cutout.png","btn":"Download CV","cv_link":"#","signature":"Maya Hartwell"}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('contact',$j${"email":"hello@hartwell.design","phone":"+1 (604) 555-0142","address":"Vancouver, BC, Canada","hours":"Mon – Fri, 9am – 5pm","socials":["Dribbble|https://dribbble.com","Behance|https://behance.net","LinkedIn|https://linkedin.com","Instagram|https://instagram.com"]}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('footer',$j${"cta_title":"Have a project in mind?","cta_accent":"Let’s build it together.","cta_btn":"Start a Project","cta_link":"/contact","about":"Product designer crafting calm, usable interfaces for startups and growing teams.","news_title":"Stay in the loop","news_text":"Occasional design notes and case studies. No spam.","news_btn":"Subscribe","legal_links":["Privacy Policy|/privacy","Terms of Use|/terms"]}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('pages',$j${"services":{"title":"Services","sub":"Design help for every stage of a product."},"about":{"title":"About Me","sub":"Designer, mentor and coffee enthusiast."},"projects":{"title":"Projects","sub":"A selection of recent product and web work."},"blog":{"title":"Blogs","sub":"Notes on design, process and craft."},"testimonials":{"title":"Testimonials","sub":"Kind words from people I’ve worked with."},"contact":{"title":"Contact Me","sub":"Tell me about your project — I reply within one working day.","form_btn":"Send Message","success":"Thanks! Your message is on its way."}}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('projects_intro',$j${"eyebrow":"Projects","title_accent":"My Latest","title":"Projects","btn":"View All Projects","link":"/projects"}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('journey_intro',$j${"eyebrow":"Education & Work","title":"My","title_accent":"Academic and","title2":"Professional Journey"}$j$::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('tools_intro',$j${"eyebrow":"My Favorite Tools","title_accent":"Exploring the Tools","title":"Behind My Designs"}$j$::jsonb) on conflict (key) do nothing;
insert into public.services(icon,title,text,sort_order,published) select icon,title,text,sort_order,published from jsonb_populate_recordset(null::public.services,$j$[{"icon":"UX","title":"UX/UI Design","text":"Research-led interfaces that feel obvious to use and a pleasure to look at.","sort_order":1,"published":true},{"icon":"◈","title":"Application Design","text":"Native and cross-platform app flows, from first sketch to polished handoff.","sort_order":2,"published":true},{"icon":"▤","title":"Website Design","text":"Marketing sites and product pages built to explain, convert and scale.","sort_order":3,"published":true}]$j$::jsonb) where not exists (select 1 from public.services);
insert into public.stats(value,label,sort_order,published) select value,label,sort_order,published from jsonb_populate_recordset(null::public.stats,$j$[{"value":"600+","label":"Projects Completed","sort_order":1,"published":true},{"value":"50+","label":"Industries Covered","sort_order":2,"published":true},{"value":"12+","label":"Years of Experience","sort_order":3,"published":true}]$j$::jsonb) where not exists (select 1 from public.stats);
insert into public.tools(name,abbr,color,percent,sort_order,published) select name,abbr,color,percent,sort_order,published from jsonb_populate_recordset(null::public.tools,$j$[{"name":"Figma","abbr":"Fg","color":"#f24e1e","percent":92,"sort_order":1,"published":true},{"name":"Sketch","abbr":"Sk","color":"#fdad00","percent":88,"sort_order":2,"published":true},{"name":"Photoshop","abbr":"Ps","color":"#001e36","percent":90,"sort_order":3,"published":true},{"name":"After Effects","abbr":"Ae","color":"#00005b","percent":85,"sort_order":4,"published":true},{"name":"Storybook","abbr":"S","color":"#ff4785","percent":90,"sort_order":5,"published":true},{"name":"InVision","abbr":"in","color":"#ff3366","percent":95,"sort_order":6,"published":true}]$j$::jsonb) where not exists (select 1 from public.tools);
insert into public.projects(title,tags,image,link,sort_order,published) select title,tags,image,link,sort_order,published from jsonb_populate_recordset(null::public.projects,$j$[{"title":"Beauty Product Mobile App Landing Page Design","tags":["UI/UX Design","Web Design","Wireframe"],"image":"/projects/p1.svg","link":"/projects","sort_order":1,"published":true},{"title":"E-commerce Mobile App Design System","tags":["UI/UX Design","Web Design","Wireframe"],"image":"/projects/p2.svg","link":"/projects","sort_order":2,"published":true},{"title":"Coffee Shop Mobile App Landing Page Design","tags":["UI/UX Design","Web Design","Wireframe"],"image":"/projects/p3.svg","link":"/projects","sort_order":3,"published":true},{"title":"Travel Booking Dashboard and Web Design","tags":["UI/UX Design","Web Design","Wireframe"],"image":"/projects/p4.svg","link":"/projects","sort_order":4,"published":true}]$j$::jsonb) where not exists (select 1 from public.projects);
insert into public.journey(kind,period,title,place,sort_order,published) select kind,period,title,place,sort_order,published from jsonb_populate_recordset(null::public.journey,$j$[{"kind":"education","period":"2012 – 2016","title":"B.Des, Interaction Design","place":"Emily Carr University","sort_order":1,"published":true},{"kind":"education","period":"2016 – 2018","title":"M.Des, Human-Centred Design","place":"OCAD University","sort_order":2,"published":true},{"kind":"work","period":"2018 – 2021","title":"Senior Product Designer","place":"Northwind Labs","sort_order":3,"published":true},{"kind":"work","period":"2021 – Now","title":"Lead Product Designer","place":"Brightside Studio","sort_order":4,"published":true}]$j$::jsonb) where not exists (select 1 from public.journey);
insert into public.posts(title,slug,category,date,image,excerpt,body,sort_order,published) select title,slug,category,date,image,excerpt,body,sort_order,published from jsonb_populate_recordset(null::public.posts,$j$[{"title":"Design systems that actually scale","slug":"design-systems-that-scale","category":"Systems","date":"2026-05-12","image":"/projects/p1.svg","excerpt":"A small set of rules beats a giant component library.","body":"A small set of rules beats a giant component library.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":1,"published":true},{"title":"User research in one week","slug":"research-in-a-week","category":"Research","date":"2026-06-12","image":"/projects/p2.svg","excerpt":"A lightweight sprint for teams with no research budget.","body":"A lightweight sprint for teams with no research budget.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":2,"published":true},{"title":"Small details that create delight","slug":"designing-for-delight","category":"Craft","date":"2026-07-12","image":"/projects/p3.svg","excerpt":"Micro-interactions that earn their place.","body":"Micro-interactions that earn their place.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":3,"published":true},{"title":"Developer handoff without tears","slug":"handoff-without-tears","category":"Process","date":"2026-08-12","image":"/projects/p4.svg","excerpt":"How to ship pixel-true work with fewer meetings.","body":"How to ship pixel-true work with fewer meetings.\n\nStart with the problem, not the screen. Map the people, the moment and the outcome before opening your design tool.\n\nThen build small, test early and keep a changelog so everyone can see why decisions were made.","sort_order":4,"published":true}]$j$::jsonb) where not exists (select 1 from public.posts);
insert into public.testimonials(name,role,rating,avatar,text,sort_order,published) select name,role,rating,avatar,text,sort_order,published from jsonb_populate_recordset(null::public.testimonials,$j$[{"name":"Priya Nair","role":"CEO, Lumen Health","rating":5,"avatar":"https://randomuser.me/api/portraits/women/32.jpg","text":"Maya turned a messy brief into a product our customers love. Clear thinking, fast iterations and zero drama.","sort_order":1,"published":true},{"name":"Daniel Ortiz","role":"Founder, Kettle & Co","rating":5,"avatar":"https://randomuser.me/api/portraits/men/51.jpg","text":"Maya turned a messy brief into a product our customers love. Clear thinking, fast iterations and zero drama.","sort_order":2,"published":true},{"name":"Sofia Rossi","role":"Head of Product, Orbit","rating":5,"avatar":"https://randomuser.me/api/portraits/women/68.jpg","text":"Maya turned a messy brief into a product our customers love. Clear thinking, fast iterations and zero drama.","sort_order":3,"published":true},{"name":"Marcus Lee","role":"CTO, Brightpath","rating":5,"avatar":"https://randomuser.me/api/portraits/men/75.jpg","text":"Maya turned a messy brief into a product our customers love. Clear thinking, fast iterations and zero drama.","sort_order":4,"published":true}]$j$::jsonb) where not exists (select 1 from public.testimonials);
insert into public.faqs(question,answer,sort_order,published) select question,answer,sort_order,published from jsonb_populate_recordset(null::public.faqs,$j$[{"question":"How do projects start?","answer":"We begin with a short call, then I send a scoped proposal within two days.","sort_order":1,"published":true},{"question":"How long does a typical project take?","answer":"Most app or website designs take four to eight weeks.","sort_order":2,"published":true},{"question":"Do you work with startups?","answer":"Yes — roughly half of my clients are early-stage teams.","sort_order":3,"published":true},{"question":"What do I receive at the end?","answer":"Figma files, a design system, prototypes and handoff notes.","sort_order":4,"published":true}]$j$::jsonb) where not exists (select 1 from public.faqs);
insert into public.contact_messages(name,email,subject,message,status,created_at) select name,email,subject,message,status,created_at from jsonb_populate_recordset(null::public.contact_messages,$j$[{"name":"Sam Rivera","email":"sam@example.com","subject":"","message":"Love your work. Are you free in March?","status":"new","created_at":"2026-10-01T10:00:00Z"}]$j$::jsonb) where not exists (select 1 from public.contact_messages);
insert into public.subscribers(email,status,created_at) select email,status,created_at from jsonb_populate_recordset(null::public.subscribers,$j$[{"email":"reader@example.com","status":"active","created_at":"2026-10-02T09:00:00Z"}]$j$::jsonb) where not exists (select 1 from public.subscribers);
